insert into question_pyq_meta (question_id, appear_count, years, exams, verified)
select id, appear_count, coalesce((select array_agg(v::int) from jsonb_array_elements_text(years) as v), '{}')::int[], coalesce((select array_agg(v) from jsonb_array_elements_text(exams) as v), '{}')::text[], verified
from jsonb_to_recordset($json$[{"id":"che-st-151","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"The integer $n$ that converts an empirical formula into the molecular formula is calculated as","options":["empirical mass / molecular mass","molecular mass / empirical formula mass","atomic number / mass number","percentage of carbon / 12"],"answer_index":1,"explanation":"$n = M / E$, then each empirical subscript is multiplied by $n$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-152","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"For an ionic solid such as $\\mathrm{Na_2CO_3}$, the formula written on the bottle is already","options":["a molecular formula that can be halved","the empirical formula of the compound","only a percentage composition","an unbalanced equation"],"answer_index":1,"explanation":"Ionic compounds are represented by the simplest ratio of ions, which is the empirical formula.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-153","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon analyses as 80% carbon and 20% hydrogen by mass. Its empirical formula is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_5}$"],"answer_index":2,"explanation":"Mole ratio C : H $= (80/12) : (20/1) = 6.67 : 20 = 1 : 3$, so $\\mathrm{CH_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-154","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A compound contains 40.0% C, 6.7% H and 53.3% O. The empirical formula matching these percentages is","options":["$\\mathrm{CHO}$","$\\mathrm{CH_2O}$","$\\mathrm{C_2H_2O}$","$\\mathrm{C_2H_6O}$"],"answer_index":1,"explanation":"Moles C : H : O $= 3.33 : 6.7 : 3.33 = 1 : 2 : 1$, which is $\\mathrm{CH_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-155","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A vapour has empirical formula CH and a vapour density corresponding to $M = 78$ g mol$^{-1}$. The molecular formula of the vapour is","options":["$\\mathrm{C_2H_2}$","$\\mathrm{C_3H_3}$","$\\mathrm{C_6H_6}$","$\\mathrm{C_{12}H_{12}}$"],"answer_index":2,"explanation":"Empirical mass 13; $n = 78/13 = 6$, giving $\\mathrm{C_6H_6}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-156","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"An iron oxide is 70% Fe and 30% O by mass (Fe = 56, O = 16). The oxide’s empirical formula is","options":["$\\mathrm{FeO}$","$\\mathrm{Fe_2O_3}$","$\\mathrm{Fe_3O_4}$","$\\mathrm{FeO_2}$"],"answer_index":1,"explanation":"Moles Fe : O $= (70/56) : (30/16) = 1.25 : 1.875 = 2 : 3$, so $\\mathrm{Fe_2O_3}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-157","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A hydrocarbon is 85.7% carbon, the rest hydrogen. The empirical formula of that hydrocarbon is","options":["$\\mathrm{CH}$","$\\mathrm{CH_2}$","$\\mathrm{CH_3}$","$\\mathrm{C_2H_2}$"],"answer_index":1,"explanation":"C : H moles $= (85.7/12) : (14.3/1) \\approx 7.14 : 14.3 = 1 : 2$, hence $\\mathrm{CH_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-158","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"A chloro-compound is 24.24% C, 4.04% H and 71.72% Cl. Its molar mass is 99 g mol$^{-1}$. The molecular formula is","options":["$\\mathrm{CH_2Cl}$","$\\mathrm{C_2H_4Cl_2}$","$\\mathrm{C_2H_3Cl}$","$\\mathrm{C_3H_6Cl_2}$"],"answer_index":1,"explanation":"Empirical moles give $\\mathrm{CH_2Cl}$ (E = 49.5); $n = 99/49.5 = 2$, so $\\mathrm{C_2H_4Cl_2}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"empirical-molecular","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-159","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"In the Haber equation $\\mathrm{N_2} + 3\\mathrm{H_2} \\rightarrow 2\\mathrm{NH_3}$, each mole of nitrogen that reacts consumes hydrogen amounting to","options":["1 mol","2 mol","3 mol","6 mol"],"answer_index":2,"explanation":"The coefficient of $\\mathrm{H_2}$ is 3, so the mole ratio N$_2$ : H$_2$ is 1 : 3.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-st-160","chapter_id":"chemistry-stoichiometry","subject_id":"chemistry","stem":"According to $2\\mathrm{H_2} + \\mathrm{O_2} \\rightarrow 2\\mathrm{H_2O}$, complete use of 1 mol of oxygen produces water equal to","options":["1 mol","2 mol","0.5 mol","4 mol"],"answer_index":1,"explanation":"One mole of $\\mathrm{O_2}$ corresponds to two moles of $\\mathrm{H_2O}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"equation-mole-ratio","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
